-- 由 deploy/tools/gen-farm-seed.py 生成，不要手改。第一期页面按钮级权限（type=3）的增量脚本，可重复执行：
--   1) 新增按钮菜单（已存在的 id 跳过）；2) 授予所有 tenant_admin 角色（已有的跳过）；3) 追加进所有租户套餐的 menu_ids（已含的跳过）。
-- 共 44 个按钮，菜单 id 120601~135204（含 +100000 偏移）。
BEGIN;
SELECT nextval('system_role_menu_seq'), r.id, m.id, 'admin', r.tenant_id
FROM system_role r CROSS JOIN unnest(ARRAY[132101, 132102, 132103, 132104, 131101, 131102, 131103, 131104, 131201, 131202, 131203, 133101, 133102, 133103, 133401, 133402, 133403, 133404, 133301, 133302, 133303, 133304, 133305, 133306, 133201, 133202, 135101, 135102, 135103, 135104, 135105, 135201, 135202, 135203, 135204, 134201, 134202, 134203, 134101, 134102, 134103, 120601, 120602, 120603]::bigint[]) AS m(id)
WHERE r.code = 'tenant_admin' AND r.deleted = 0
  AND EXISTS (SELECT 1 FROM system_menu x WHERE x.id = m.id)
  AND NOT EXISTS (SELECT 1 FROM system_role_menu e WHERE e.role_id = r.id AND e.menu_id = m.id AND e.deleted = 0);
UPDATE system_tenant_package p
SET menu_ids = (p.menu_ids::jsonb || (SELECT COALESCE(jsonb_agg(i), '[]'::jsonb) FROM unnest(ARRAY[132101, 132102, 132103, 132104, 131101, 131102, 131103, 131104, 131201, 131202, 131203, 133101, 133102, 133103, 133401, 133402, 133403, 133404, 133301, 133302, 133303, 133304, 133305, 133306, 133201, 133202, 135101, 135102, 135103, 135104, 135105, 135201, 135202, 135203, 135204, 134201, 134202, 134203, 134101, 134102, 134103, 120601, 120602, 120603]::bigint[]) AS i WHERE NOT (p.menu_ids::jsonb @> to_jsonb(i))))::text
WHERE p.deleted = 0;
SELECT setval('system_role_menu_seq', GREATEST((SELECT COALESCE(MAX(id), 0) FROM system_role_menu) + 1, nextval('system_role_menu_seq')), false);
COMMIT;
